import {ToastService} from 'ng-zorro-antd-mobile';

export function dealApiData(data) {
    const result = {
        isSuccess: true,
        data: data.data
    };
    switch (data.code) {
        case 1:
            break;
        case 100:
            result.isSuccess = false;
            break;
        default:
            result.isSuccess = false;
            failMessage(data.message);
            break;
    }
    return result;
}

export function dealApiDataPage(data) {
    const result = {
        isSuccess: true,
        data: data.data,
        pageNum: data.pageNum,
        pageSize: data.pageSize,
        pages: data.pages,
        total: data.total
    };
    switch (data.code) {
        case 1:
            break;
        case 100:
            result.isSuccess = false;
            break;
        default:
            result.isSuccess = false;
            failMessage(data.message);
            break;
    }
    return result;
}

export function successMessage(value) {
    ToastService.prototype.success(value);
}

export function failMessage(value) {
    ToastService.prototype.fail(value);
}

export function showMessage(value) {
    ToastService.prototype.show(value);
}
