import {Inject, Injectable} from '@angular/core';
import {
    HttpEvent, HttpInterceptor, HttpHandler, HttpRequest, HttpResponse, HttpClient
} from '@angular/common/http';

import {Observable, Subscriber, throwError} from 'rxjs';
import {catchError, tap, timeout} from 'rxjs/operators';
import {Router} from '@angular/router';
import {HttpClientService} from '../shared/http-client.service';
import {ModalService} from 'ng-zorro-antd-mobile';
import {isNotNullOrUndefined} from "codelyzer/util/isNotNullOrUndefined";

/** Pass untouched request through to the next request handler. */
@Injectable()
export class DefaultInterceptor implements HttpInterceptor {
    constructor(
        private http: HttpClientService,
        private router: Router,
    ){
    }

    /** 记录 */
    ReqList: ImplReqList[] = [];

    intercept(req: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
       let isShowLog = false;
       if(isNotNullOrUndefined(sessionStorage.getItem('isShowLog')) &&
           sessionStorage.getItem('isShowLog') === 'true'){
           isShowLog = true;
       } else {
           isShowLog = false;
       }
        const authReq = req.clone();
        return new Observable(observer => {
            next.handle(authReq).pipe(
                catchError(error => {
                    if (error.status === 401 && req.url.indexOf('token/refresh') === -1) {
                        if (sessionStorage.getItem('isRefreshingToken') === '1') {
                          sessionStorage.setItem('isRefreshingToken', '0');
                          if(isShowLog){
                              console.log('开始刷新token');
                          }
                          return this.http.refresh().pipe(
                            tap(event => {
                               if(isShowLog){
                                   console.log('刷新token返回', event);
                                 }
                              // 更新refreshToken 用于下次再次更新token时传参
                              sessionStorage.setItem('Authorization', event.headers.get('Authorization'));
                              sessionStorage.setItem('Authorization-Refresh', event.headers.get('Authorization-Refresh'));
                              //  更新header的token
                              sessionStorage.setItem('isRefreshingToken', '1');
                              const authReq2 = authReq.clone({ setHeaders: { Authorization: event.headers.get('Authorization') } });
                              next.handle(authReq2).pipe(
                                tap(
                                  event2 => {
                                      if(isShowLog) {
                                          console.log('发起当前token失败的请求authReq：', authReq.url);
                                      }
                                      observer.next(event2);
                                  },
                                    err => {
                                        // 如果刷新token时失败，说明Token 令牌过期 : 令牌已失效，需要返回到登录界面重新登录
                                        if (err.error.status === 401){
                                            this.router.navigate(['/login']);
                                        }}
                                )
                              ).subscribe(res2 => {
                                  if(isShowLog) {
                                      console.log('第一个refresh token后，重新把其他token失效的接口重新发起请求');
                                      console.log('没有token的请求', this.ReqList);
                                  }
                                this.ReqList.forEach(rl => {
                                  const r = rl.reqObj.clone({ setHeaders: { Authorization: event.headers.get('Authorization') } });
                                  rl.nextObj.handle(r).pipe(
                                    tap(
                                      event2 => {
                                          if(isShowLog) {
                                              console.log('发起当前token失败的请求rl：', rl.reqObj);
                                          }
                                          rl.observer.next(event2);
                                      }
                                    )
                                  ).subscribe(rrr => {
                                      if(isShowLog) {
                                          console.log('token刷新后重连接口', rrr);
                                      }
                                  });
                                });
                                this.ReqList = [];
                              });

                            },
                              err => {
                                    // 如果刷新token时失败，说明Token 令牌过期 : 令牌已失效，需要返回到登录界面重新登录
                                    if (err.error.status === 401){
                                        this.http.showQuitAlert();
                                    }
                              }),
                          );
                        } else {
                          // 多接口同时请求时，把其他token失效且没有调刷新token的请求，放到集合中保存
                          this.ReqList = [...this.ReqList, ...[
                            {
                              reqObj: req,
                              nextObj: next,
                              observer
                            }
                          ]];
                        }
                    } else {
                        if(isShowLog) {
                            console.log('其他错误码', error);
                        }
                        if (error.url.indexOf('/login') > -1){
                            this.http.showToast('用户名或密码错误！');
                            this.router.navigate(['/login']);
                        } else {
                            // 如果刷新token时失败，说明Token 令牌过期 : 令牌已失效，需要返回到登录界面重新登录
                            if (error.error.status === 401){
                                this.http.showQuitAlert();
                            } else {
                                ////// this.http.showToast('网络连接失败！'); 
                            }
                        }
                    }
                })
            ).subscribe(
                res => {
                    if (res instanceof HttpResponse) {
                        if (res.status === 200) {
                            observer.next(res);
                        }
                    }
                },
                err => {
                    if (err.status === 400 && err.error && err.error.error === 'invalid_grant'
                        && err.error && err.error.error_description === 'Bad credentials') {
                        // this.authService.passwordFalse = true;
                    }
                    // 提示http请求错误码
                    if (err?.url?.indexOf('/login') > -1){
                        this.http.showToast('用户名或密码错误！');
                        this.router.navigate(['/login']);
                    } else {
                        ////// this.http.showToast('网络连接失败！'); 
                    }
                });
        });
    }
}

export interface ImplReqList {
    reqObj: HttpRequest<any>;
    nextObj: HttpHandler;
    observer: Subscriber<HttpEvent<any>>;
}
